/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';
import { parseQuantity as parseCliQuantity } from './src/cli.js';

const zeroResult = lineFromRequest({ sku: ' A ', quantity: '0' });
assert.deepEqual(zeroResult, { sku: 'A', quantity: 0, active: false });
assert.deepEqual(lineFromRequest({ sku: ' A ', quantity: 0 }), zeroResult);
for (const [input, expected] of [[1, 1], [42, 42], ['1', 1], [' 42 ', 42], ['1e2', 100]]) {
  assert.deepEqual(lineFromRequest({ sku: ' A ', quantity: input }), { sku: 'A', quantity: expected, active: true });
}
const invalid = [-1, '-1', -0.5, '-0.5', 1.5, '1.5', NaN, Infinity, -Infinity, 'Infinity', 'NaN', '', ' ', '\\t\\n', true, false, null, undefined, 'abc', '1x'];
for (const quantity of invalid) {
  assert.throws(() => lineFromRequest({ sku: 'A', quantity }), { name: 'Error', message: 'invalid quantity' });
}
assert.equal(parseCliQuantity('0'), 1);
assert.equal(parseCliQuantity('-1'), -1);
assert.equal(parseCliQuantity('1.5'), 1);
let errorMessage;
try {
  lineFromRequest({ sku: 'A', quantity: '' });
  assert.fail('invalid quantity was accepted');
} catch (error) {
  assert.equal(error.message, 'invalid quantity');
  errorMessage = error.message;
}
const answer = { changed_file: 'src/quantity.js', zero_result: zeroResult, error_message: errorMessage };
writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\\n');
assert.deepEqual(JSON.parse(readFileSync('answer.json', 'utf8')), answer);
console.log("'`Passed: 2 zero cases, 5 positive cases, ${invalid.length} invalid cases, and 3 legacy CLI checks; answer.json written and read back.`);
NODE'

